/**
 * Fetches the campaign score's stems from ElevenLabs.
 *
 *   $env:ELEVENLABS_API_KEY = "..."   # never committed, never written to a file
 *   node scripts/fetch-score-stems.mjs
 *
 * ElevenLabs' Music API (`/v1/music`) composes a finished track from a prompt, and it is the right
 * tool for this. It is also gated to paid plans — on the key this project was given it answers
 * `402 paid_plan_required` — so the score is instead built from *stems* generated by
 * `/v1/sound-generation`, which the same key can reach.
 *
 * That turns out to be the better architecture anyway. A single composed track has to be cut to
 * the film; a set of stems is arranged *by* the film. `build-campaign-score.mjs` places these
 * against the beat map imported from `src/campaign/script.ts`, so the music lands on the edit
 * rather than the edit being nudged onto the music. If a paid key appears later, a composed track
 * can be dropped in as one more layer without any of this being thrown away.
 *
 * Stems are cached: a stem already on disk is not re-fetched, so re-running this is free. Delete a
 * file to regenerate just that one.
 */

import { existsSync, mkdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '..');
const STEMS = path.join(ROOT, 'public', 'audio', 'stems');

const KEY = process.env.ELEVENLABS_API_KEY;
if (!KEY) {
  console.error('ELEVENLABS_API_KEY is not set. Export it for this shell only; do not put it in a file.');
  process.exit(1);
}

/**
 * The palette.
 *
 * Everything is asked for in A minor and without melody, because a stem carrying a tune would
 * fight every other stem the moment two of them overlap. What is wanted from each of these is a
 * *texture* with a defined role in the arrangement — the tune, such as it is, comes from which
 * textures are present when.
 *
 * `prompt_influence` is high on the rhythmic and percussive stems, where drifting off-brief costs
 * the arrangement its grid, and lower on the pads, where a little interpretation is what stops
 * them sounding like a held synthesiser key.
 */
const STEM_SET = [
  {
    file: 'drone',
    seconds: 22,
    influence: 0.55,
    text: 'Deep sustained sub-bass drone in A minor, analog synthesiser, slow subtle movement, dark and warm, no drums, no melody, no rhythm, clean studio recording, seamless loop',
  },
  {
    file: 'pad',
    seconds: 22,
    influence: 0.5,
    text: 'Slowly evolving cinematic ambient pad in A minor, warm vintage analog synthesiser, soft filter movement, restrained and minimal, no drums, no melody, no arpeggio, seamless',
  },
  {
    file: 'pad-warm',
    seconds: 22,
    influence: 0.5,
    text: 'Warm major-sixth ambient synthesiser chord swell, hopeful but restrained, analog tape character, slow attack, no drums, no melody, seamless',
  },
  {
    file: 'pulse',
    seconds: 22,
    influence: 0.75,
    // First attempt asked for "soft, dry, no reverb tail" and came back 48 dB below full scale —
    // effectively silence. Asking for a *clearly audible* repeating note is what fixed it.
    text: 'Clearly audible repeating deep muted synthesiser bass note, one note per second, steady rhythmic pulse, strong and present in the mix, dry close studio recording, no melody, no drums',
  },
  {
    file: 'perc-sparse',
    seconds: 22,
    influence: 0.8,
    text: 'Sparse tactile minimal percussion, soft rim clicks and muted wooden taps, dry and close-mic, mechanical and precise, steady slow tempo, no music, no melody, no cymbals',
  },
  {
    file: 'perc-drive',
    seconds: 22,
    influence: 0.8,
    text: 'Driving minimal electronic percussion loop, tight muted kick and crisp shaker and rim, precise and controlled, modern cinematic technology score, steady tempo, no melody, no vocals',
  },
  {
    file: 'machine',
    seconds: 20,
    influence: 0.7,
    // Same correction: "quiet" and "distant" produced a stem 40 dB down that vanished under
    // everything else in the mix.
    text: 'Audible mechanical room tone, steady electrical hum with irregular relay clicks, close-mic and present, cold industrial, no music, no melody',
  },
  {
    file: 'riser',
    seconds: 12,
    influence: 0.7,
    text: 'Slow controlled cinematic riser, filtered noise and rising synthesiser tone, tension building smoothly, no impact at the end, no drums',
  },
  {
    file: 'impact',
    seconds: 6,
    influence: 0.75,
    text: 'Deep clean cinematic sub-bass impact, tight and controlled, short decay, premium technology brand reveal, no reverb wash, no distortion',
  },
  {
    file: 'shimmer',
    seconds: 20,
    influence: 0.5,
    text: 'High delicate crystalline synthesiser shimmer, airy and quiet, slow movement, sits far back in the mix, no melody, no drums, seamless',
  },
  {
    file: 'resolve',
    seconds: 20,
    influence: 0.55,
    text: 'Full warm resolved A minor synthesiser chord with long natural decay to silence, cinematic ending, analog strings and soft brass texture, no drums, no melody',
  },
  {
    file: 'tick',
    seconds: 4,
    influence: 0.85,
    text: 'Single soft tactile interface click, dry and premium, very short, no reverb, no tone',
  },
];

mkdirSync(STEMS, { recursive: true });

let fetched = 0;
let cached = 0;

for (const stem of STEM_SET) {
  const destination = path.join(STEMS, `${stem.file}.mp3`);
  if (existsSync(destination)) {
    cached += 1;
    console.log(`cached  ${stem.file}`);
    continue;
  }

  const response = await fetch('https://api.elevenlabs.io/v1/sound-generation', {
    method: 'POST',
    headers: { 'xi-api-key': KEY, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      text: stem.text,
      duration_seconds: stem.seconds,
      prompt_influence: stem.influence,
    }),
  });

  if (!response.ok) {
    const detail = await response.text();
    throw new Error(`${stem.file}: ${response.status} ${detail.slice(0, 300)}`);
  }

  const buffer = Buffer.from(await response.arrayBuffer());
  writeFileSync(destination, buffer);
  fetched += 1;
  console.log(`fetched ${stem.file.padEnd(14)} ${stem.seconds}s  ${(buffer.length / 1024).toFixed(0)} kB`);
}

console.log(`\n${fetched} fetched, ${cached} cached -> public/audio/stems/`);
